            this.publish(SUBMITTED_TERM_CHANGED_EVENT)
        }
        this.searchFrom(this.searchOrigin, 'next')
    }

    selectNext() {
        if (!this.submittedTerm) return

        this.searchFrom(this.activeMatch?.end ?? 0, 'next')
    }

    selectPrevious() {
        if (!this.submittedTerm) return

        this.searchFrom(this.activeMatch?.start ?? 0, 'previous')
    }

    handlePopupKeyDown(event: ConversationSearchKeyboardEvent) {
        const opensSearch = event.ctrlKey && !event.altKey && !event.metaKey && event.key.toLowerCase() === 'f'
        if (opensSearch && this.getTranscriptMounted()) {
            event.preventDefault()
            this.openSearch()
            return
        }
        if (event.key === 'Escape' && this.open) {
            event.preventDefault()
            event.stopPropagation()
            this.closeSearch()
            return
        }
        if (event.key !== 'F3' || !this.submittedTerm || !this.getTranscriptMounted()) return

        event.preventDefault()
        this.selectNext()
    }

    private readonly refreshMatches = () => {
        if (!this.viewport || !this.submittedTerm) return

        const searchDocument = createConversationSearchDocument(this.viewport)
        const matches = findConversationTextMatches(searchDocument.text, this.submittedTerm, this.caseSensitive)
        this.setResultCount(matches.length)
        if (!this.activeMatch) return

        const retainedMatch = matches.find(({ end, start }) => (
            start === this.activeMatch?.start && end === this.activeMatch.end
        ))
        if (!retainedMatch) {
            this.setActiveMatch(null)
            return
        }
        this.selectMatch(searchDocument, retainedMatch)
    }

    private searchFrom(offset: number, direction: ConversationSearchDirection) {
        if (!this.viewport) return

        const searchDocument = createConversationSearchDocument(this.viewport)
        const matches = findConversationTextMatches(searchDocument.text, this.submittedTerm, this.caseSensitive)
        this.setResultCount(matches.length)
        const match = findConversationTextMatch(matches, offset, direction)
        if (!match) return

        this.selectMatch(searchDocument, match)
    }

    private selectMatch(searchDocument: ConversationSearchDocument, match: ConversationTextMatch) {
        const range = rangeForMatch(searchDocument, match)
        if (!range) return

        const selection = window.getSelection()
        selection?.removeAllRanges()
        selection?.addRange(range)
        range.startContainer.parentElement?.scrollIntoView?.({ block: 'nearest' })
        this.setActiveMatch(match)
    }

    private clearOwnedSelection() {
        if (!this.activeMatch) return

        window.getSelection()?.removeAllRanges()
    }

    private setActiveMatch(match: ConversationTextMatch | null) {
        if (this.activeMatch?.start === match?.start && this.activeMatch?.end === match?.end) return

        this.activeMatch = match
        this.publish(ACTIVE_MATCH_CHANGED_EVENT)
    }

    private setResultCount(count: number) {
        if (this.resultCount === count) return

        this.resultCount = count
        this.publish(RESULT_COUNT_CHANGED_EVENT)
    }

    private disconnectObserver() {
        this.mutationObserver?.disconnect()
        this.mutationObserver = null
    }

    private subscribe(eventType: string) {
        return (listener: () => void) => {
            this.addEventListener(eventType, listener)

            return () => this.removeEventListener(eventType, listener)
        }
    }

    private publish(eventType: string) {
        this.dispatchEvent(new Event(eventType))
    }
}

import { Stack } from '@mui/material'
import { memo, useCallback, useEffect, useLayoutEffect, useRef, useState, type UIEvent } from 'react'
import { dialogService } from '../../../../services/dialog_service'
import type { ActionRunBindingStore } from '../../run/state/action_run_binding_store'
import { ActionConversationChatlogTracker } from './action_conversation_chatlog_tracker'
import { ActionConversationEvolvingGroups } from './action_conversation_evolving_groups'
import { ActionConversationHistory } from './action_conversation_history'
import { ActionConversationCompactProgress } from './action_conversation_compact_progress';
import { ActionConversationReservedBlocks } from './action_conversation_reserved_blocks'
import type { ActionConversationStore } from '../state/action_conversation_store'
import type { ActionConversationCommandOperations } from '../state/action_conversation_command_service'
import type { ActionConversationSearchService } from '../search/action_conversation_search_service'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96

interface ActionConversationTranscriptProps {
    bindingStore: ActionRunBindingStore
    commands: ActionConversationCommandOperations
    searchService: ActionConversationSearchService
    store: ActionConversationStore
    trackerFactory?: (
        bindingStore: ActionRunBindingStore,
        store: ActionConversationStore,
    ) => ActionConversationChatlogTracker
}

function createChatlogTracker(bindingStore: ActionRunBindingStore, store: ActionConversationStore) {
    return new ActionConversationChatlogTracker(bindingStore, store)
}

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

/** Owns tracker lifecycle and renders subscribed transcript leaves. */
export const ActionConversationTranscript = memo(function ActionConversationTranscript(
    { bindingStore, commands, searchService, store, trackerFactory = createChatlogTracker }: ActionConversationTranscriptProps,
) {
    const [tracker, setTracker] = useState<ActionConversationChatlogTracker | null>(null)
    const viewportRef = useRef<HTMLDivElement>(null)
    const viewportHeightRef = useRef<number | null>(null)
    const conversationIdentityRef = useRef<string | null>(null)
    const stuckToEndRef = useRef(true)

    const scrollToEnd = useCallback(() => {
        const viewport = viewportRef.current
        if (!viewport || !stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    }, [])

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    const handleViewportResize = useCallback(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const previousViewportHeight = viewportHeightRef.current
        const viewportHeight = viewport.clientHeight
        viewportHeightRef.current = viewportHeight
        if (previousViewportHeight === viewportHeight) return

        scrollToEnd()
    }, [scrollToEnd])

    useEffect(() => {
        const nextTracker = trackerFactory(bindingStore, store)
        setTracker(null)
        try {
            nextTracker.load()
            setTracker(nextTracker)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not load conversation chatlog' })
        }

        return () => nextTracker.unload()
    }, [bindingStore, store, trackerFactory])

    useEffect(() => {
        if (!tracker) return undefined

        const handleContentChange = () => {
            scrollToEnd()
            queueMicrotask(scrollToEnd)
        }
        const handleConversationChange = () => {
            const conversationIdentity = tracker.getConversationIdentity()
            if (conversationIdentityRef.current !== conversationIdentity) stuckToEndRef.current = true
            conversationIdentityRef.current = conversationIdentity
            searchService.updateConversation(conversationIdentity)
            handleContentChange()
        }
        conversationIdentityRef.current = tracker.getConversationIdentity()
        const unsubscribers = [
            tracker.subscribeStableGroups(handleContentChange),
            tracker.subscribeEvolvingGroups(handleContentChange),
            tracker.subscribeReservedBlockCount(handleContentChange),
            tracker.subscribeConversation(handleConversationChange),
        ]

        return () => {
            for (const unsubscribe of unsubscribers) unsubscribe()
        }
    }, [scrollToEnd, searchService, tracker])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport || !tracker) return undefined

        return searchService.registerTranscript(viewport, tracker.getConversationIdentity())
    }, [searchService, tracker])

    useLayoutEffect(scrollToEnd, [scrollToEnd, tracker])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        viewportHeightRef.current = viewport.clientHeight
        const resizeObserver = new ResizeObserver(handleViewportResize)
        resizeObserver.observe(viewport)

        return resizeObserver.disconnect.bind(resizeObserver)
    }, [handleViewportResize])

    return (
        <Stack aria-label="Conversation chat" onScroll={handleScroll} ref={viewportRef} spacing={1}
            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}>
            {tracker ? <ActionConversationHistory commands={commands} tracker={tracker} /> : null}
            {tracker ? <ActionConversationEvolvingGroups commands={commands} tracker={tracker} /> : null}
            {tracker ? <ActionConversationReservedBlocks tracker={tracker} /> : null}
            {tracker ? <ActionConversationCompactProgress onContentChange={scrollToEnd} tracker={tracker} /> : null}
        </Stack>
    )
})

import { Box, Stack, Typography } from '@mui/material'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { ActionConversationChat } from '../../conversation/action_conversation_chat'
import { ActionScheduleOwner } from '../schedule/action_schedule_owner'
import { ActionRunHistoryOwner } from '../state/action_run_history_owner'
import { ActionPromptOwner } from '../../agent/action_prompt_owner';
import { ActionAgentApprovals } from '../../agent/action_agent_approvals';
import { ActionLogErrorOwner } from '../../conversation/errors/action_log_error_owner';
import { ActionRunStatusOwner } from '../state/action_run_status_owner';
import { ActionInputSplitter } from './action_input_splitter';
import { ActionLayoutSurface } from './action_layout_surface';
import { ActionRunDisabledMessage } from './action_run_disabled_message'
import type { ActionPopupRuntime } from './action_popup_types'

interface AgentActionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    baseContext: ActionContext
    popupEntryId?: string
    popupVisible?: boolean
    readOnlyMessage: string | null
    runtime: ActionPopupRuntime
    showHistoricalHistory?: boolean
}

/** Agent conversation, prompt, interaction, and scheduling content. */
export function AgentAction(props: AgentActionProps) {
    const { action, assignmentContext, baseContext, popupEntryId, popupVisible, readOnlyMessage, runtime, showHistoricalHistory } = props
    const {
        agentLayoutStore, bindingStore, conversationSearchService, conversationStore, historyStore,
        inputStore, resultStore, usageValuesService,
    } = runtime;
    const { runValidationError, scheduleStore, settingsStore } = runtime

    if (readOnlyMessage) {
        return (
            <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                <ActionConversationChat
                    actionId={action.id}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    popupEntryId={popupEntryId}
                    popupVisible={popupVisible}
                    searchService={conversationSearchService}
                    store={conversationStore}
                />
                {showHistoricalHistory ? <ActionRunHistoryOwner store={historyStore} /> : null}
                <Typography color="text.secondary" role="note" variant="caption">{readOnlyMessage}</Typography>
            </Stack>
        )
    }

    return (
        <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
            <ActionScheduleOwner action={action} context={baseContext} store={scheduleStore} />
            {action.type === 'command' ? <ActionRunStatusOwner bindingStore={bindingStore} resultStore={resultStore} /> : null}
            <ActionRunDisabledMessage action={action} settingsStore={settingsStore} />
            {runValidationError ? (
                <Typography color="error.main" role="alert" variant="caption">
                    {runValidationError}
                </Typography>
            ) : null}
            <ActionLayoutSurface store={agentLayoutStore}>
                <Box data-layout-adjacent sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, overflowY: 'auto' }}>
                    <ActionLogErrorOwner bindingStore={bindingStore} resultStore={resultStore} />
                    <ActionConversationChat
                        actionId={action.id}
                        bindingStore={bindingStore}
                        context={assignmentContext}
                        popupEntryId={popupEntryId}
                        popupVisible={popupVisible}
                        searchService={conversationSearchService}
                        store={conversationStore}
                        usageValuesService={action.type === 'agent'
                            && (assignmentContext.kind === 'project'
                                || (assignmentContext.kind === 'card' && !!assignmentContext.file && !!assignmentContext.cardInternalId))
                            ? usageValuesService : undefined}
                    />
                </Box>
                <ActionInputSplitter store={agentLayoutStore} />
                <ActionPromptOwner
                    action={action}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    layoutStore={agentLayoutStore}
                    questionsEnabled
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                    settingsStore={settingsStore}
                />
            </ActionLayoutSurface>
            <ActionAgentApprovals bindingStore={bindingStore} />
            {showHistoricalHistory || action.type === 'command' ? (
                <Box sx={{ flexShrink: 1, minHeight: 0, overflowY: 'auto' }}><ActionRunHistoryOwner store={historyStore} /></Box>
            ) : null}
        </Stack>
    )
}

import { Stack } from '@mui/material'
import { useEffect, useMemo, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { useBoundRunId, useRunSelector } from '../../hooks/use_action_runs'
import {
    ActionConversationTranscript,
} from './transcript/action_conversation_transcript'
import {
    createAcknowledgementConversationSelector,
} from './state/action_conversation_chat_selectors'
import { resolveDisplayedConversation, type ActionConversationStore } from './state/action_conversation_store'
import { ConversationMetaInfo } from './status/conversation_meta_info'
import { ActionConversationCommandService } from './state/action_conversation_command_service'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import type { ActionUsageValuesService } from '../run/popup/action_usage_values_service'
import type { ActionConversationSearchService } from './search/action_conversation_search_service'

interface ActionConversationChatProps {
    actionId: string
    bindingStore: ActionRunBindingStore
    context: ActionContext
    popupEntryId?: string
    popupVisible?: boolean
    searchService: ActionConversationSearchService
    store: ActionConversationStore
    usageValuesService?: ActionUsageValuesService
}

/** Conversation surface; owns selection, live-run, visibility, and acknowledgement subscriptions. */
export function ActionConversationChat(
    {actionId, bindingStore, context, popupEntryId, popupVisible, searchService, store, usageValuesService}: ActionConversationChatProps,
) {
    const selectAcknowledgementConversation = useMemo(() => createAcknowledgementConversationSelector(), [])
    const commands = useMemo(
        () => new ActionConversationCommandService(actionId, context, store),
        [actionId, context, store],
    )
    const boundRunId = useBoundRunId(bindingStore)
    const liveConversation = useRunSelector(boundRunId, selectAcknowledgementConversation)
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const conversation = resolveDisplayedConversation(liveConversation, selectedConversation)
    const scope = context.cardInternalId ?? null
    const visible = !!popupEntryId && !!popupVisible && !!conversation

    useEffect(() => {
        if (!popupEntryId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, scope, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId, scope, actionId, conversation, false,
        )
    }, [actionId, conversation, popupEntryId, scope, visible])

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <ActionConversationTranscript
                bindingStore={bindingStore}
                commands={commands}
                searchService={searchService}
                store={store}
            />
            <ConversationMetaInfo bindingStore={bindingStore} store={store} usageValuesService={usageValuesService} />
        </Stack>
    )
}

import { AgentAction } from './agent_action'
import { CommandAction } from './command_action'
import type { ActionPopupContentProps, ActionPopupRuntime } from './action_popup_types'

interface ActionPopupSessionProps extends ActionPopupContentProps {
    runtime: ActionPopupRuntime;
}

/** Renders selected bindings without an action-keyed frame or agent editor. */
export function ActionPopupSession(props: ActionPopupSessionProps) {
    const { action, assignmentContext, historicalEntries, runtime } = props;

    return (
        <>
            {action.type === 'agent'
                ? (
                    <AgentAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        popupEntryId={props.popupEntryId}
                        popupVisible={props.popupVisible}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                        showHistoricalHistory={!!historicalEntries}
                    />
                ) : (
                    <CommandAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                        showHistoricalHistory={!!historicalEntries}
                    />
                )}
        </>
    )
}

import { useLayoutEffect, useState, useSyncExternalStore } from 'react';
import { ActionPopupFrame } from './action_popup_frame';
import { ActionPopupSession } from './action_popup_session';
import { ActionPopupSessionService } from './action_popup_session_service';
import type { ActionPopupContentProps } from './action_popup_types';

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_frame';

/** Keeps the popup surface and agent editor mounted while services switch action bindings. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const { action, assignmentContext, historicalEntries, initialConversationPath, initialRunId } = props;
    const [service] = useState(() => new ActionPopupSessionService());
    const selected = useSyncExternalStore(service.subscribe, service.getSnapshot, service.getSnapshot);
    useLayoutEffect(() => {
        service.select(action, assignmentContext, initialRunId, initialConversationPath, historicalEntries);
    }, [action, assignmentContext, historicalEntries, initialConversationPath, initialRunId, service]);
    useLayoutEffect(() => () => service.dispose(), [service]);
    if (!selected) return null;

    const contentProps = { ...props, action: selected.action, assignmentContext: selected.context };
    const { bindingStore, conversationSearchService, conversationStore } = selected.runtime;
    return (
        <ActionPopupFrame bindingStore={bindingStore} contentProps={contentProps}
            conversationSearchService={conversationSearchService} conversationStore={conversationStore}>
            <ActionPopupSession {...contentProps} runtime={selected.runtime} />
        </ActionPopupFrame>
    );
}

